package termui

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

var updateBootstrap = flag.Bool("update-bootstrap-banner", false, "regenerate the source bootstrap banner script")

// The shell entry point needs a banner before Go can compile itself. Generate
// its variants from the runtime renderer so the two presentations cannot drift.
func TestBootstrapBannerMatchesRuntimeRenderer(t *testing.T) {
	var script strings.Builder
	script.WriteString(`#!/bin/sh
# Generated by: go test ./internal/termui -run TestBootstrapBannerMatchesRuntimeRenderer -update-bootstrap-banner
# Print before invoking Go, including on a cold cache or without Go installed.
set -eu
if [ ! -t 1 ] || [ "${TERM:-}" = dumb ] || [ -n "${CI:-}" ] || [ -n "${ONIBI_PLAIN:-}" ]; then
  printf '%s\n' 'Onibi / Control Ghostty wherever text renders'
  exit 0
fi
onibi_size=$(stty size <&1 2>/dev/null) || onibi_size='24 80'
set -- $onibi_size
onibi_columns=${2:-80}
case "$onibi_columns" in ''|*[!0-9]*) onibi_columns=80 ;; esac
if [ "$onibi_columns" -eq 0 ]; then onibi_columns=80; fi
onibi_width=compact
if [ "$onibi_columns" -ge 64 ]; then
  onibi_width=wide
elif [ "$onibi_columns" -lt 39 ]; then
  printf '\n  ONIBI\n\n'
  exit 0
fi
onibi_locale=${LC_ALL:-${LC_CTYPE:-${LANG:-C}}}
onibi_ascii=1
case "$onibi_locale" in *[Uu][Tt][Ff]*) onibi_ascii=0 ;; esac
onibi_plain=0
if [ -n "${NO_COLOR:-}" ]; then onibi_plain=1; fi
case "$onibi_width:$onibi_ascii:$onibi_plain" in
`)
	for _, size := range []struct {
		name    string
		columns int
	}{{"wide", 96}, {"compact", 60}} {
		for _, ascii := range []bool{false, true} {
			for _, plain := range []bool{false, true} {
				var out bytes.Buffer
				ui := &UI{Out: &out, Interactive: true, ASCII: ascii, NoStyle: plain, width: size.columns}
				ui.Banner("Control Ghostty wherever text renders")
				text := strings.ReplaceAll(out.String(), "\x1b", "\\033")
				// This generated art/tagline contains no shell quotes, substitutions or
				// arbitrary user input. Keep that constraint explicit when updating it.
				if strings.ContainsAny(text, "'`$") {
					t.Fatal("unsafe generated shell literal")
				}
				a, p := 0, 0
				if ascii {
					a = 1
				}
				if plain {
					p = 1
				}
				fmt.Fprintf(&script, "  %s:%d:%d) printf '%%b' '%s' ;;\n", size.name, a, p, text)
			}
		}
	}
	script.WriteString("esac\n")
	path := filepath.Join("..", "..", "scripts", "onibi-banner.sh")
	if *updateBootstrap {
		if err := os.WriteFile(path, []byte(script.String()), 0644); err != nil {
			t.Fatal(err)
		}
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if string(raw) != script.String() {
		t.Fatal("bootstrap banner differs from renderer; regenerate with -update-bootstrap-banner")
	}
}
